import re
for fn in ['sheet2.xml','sheet3.xml']:
    xml = open('xl/worksheets/'+fn).read()
    print('===', fn, 'len', len(xml))
    rows = re.findall(r'<row r="(\d+)"[^>]*>(.*?)</row>', xml, re.S)
    print('num rows', len(rows))
    vals = []
    for r, content in rows:
        cells = re.findall(r'<c r="([A-Z]+\d+)"[^>]*>(.*?)</c>', content, re.S)
        rowvals = {}
        for ref, cell in cells:
            v = re.search(r'<v>(.*?)</v>', cell, re.S)
            if v:
                rowvals[ref] = v.group(1)
        if rowvals:
            vals.append((r, rowvals))
    print('rows with any value:', len(vals))
    for item in vals[:20]:
        print(item)
