cd /tmp && python3 << 'EOF'
import os, zipfile, re
# search all xlsx in /tmp for workbooks whose sheets have matching dimensions
for root, dirs, files in os.walk('/tmp'):
    for f in files:
        if f.endswith('.xlsx') and not f.startswith('~'):
            p = os.path.join(root, f)
            try:
                z = zipfile.ZipFile(p)
                wb = z.read('xl/workbook.xml').decode('utf-8','ignore')
                names = re.findall(r'name="([^"]+)"', wb)
                if 'master' in names and 'Hrs' in names and 'amount' in names:
                    # get dimensions
                    dims=[]
                    for n in z.namelist():
                        if re.match(r'xl/worksheets/sheet\d+\.xml', n):
                            s = z.read(n).decode('utf-8','ignore')
                            m = re.search(r'<dimension ref="([^"]+)"', s)
                            dims.append((n, m.group(1) if m else '?'))
                    print(p, names, dims)
            except Exception as e:
                pass
